import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void max_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner)
{
  // Each block handles one "outer" slice and a tile of "inner" columns.
  int o = blockIdx.x;
  int inner_idx = blockIdx.y * blockDim.x + threadIdx.x;
  if (inner_idx >= Inner) return;

  // View the o-th slice as a (Reduce, Inner) matrix, row-major:
  // stride along reduce-dim = Inner, stride along inner-dim = 1.
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)o * (int64_t)Reduce * (int64_t)Inner),
      make_shape(Reduce, Inner),
      make_stride(Inner, Int<1>{})
  );

  T maxval;
  int r = 0;
  if (Reduce >= 8) {
    T max0 = mX(0, inner_idx);
    T max1 = mX(1, inner_idx);
    T max2 = mX(2, inner_idx);
    T max3 = mX(3, inner_idx);
    T max4 = mX(4, inner_idx);
    T max5 = mX(5, inner_idx);
    T max6 = mX(6, inner_idx);
    T max7 = mX(7, inner_idx);
    r = 8;
    #pragma unroll 4
    for (; r + 7 < Reduce; r += 8) {
      T v0 = mX(r + 0, inner_idx);
      T v1 = mX(r + 1, inner_idx);
      T v2 = mX(r + 2, inner_idx);
      T v3 = mX(r + 3, inner_idx);
      T v4 = mX(r + 4, inner_idx);
      T v5 = mX(r + 5, inner_idx);
      T v6 = mX(r + 6, inner_idx);
      T v7 = mX(r + 7, inner_idx);
      max0 = (v0 > max0) ? v0 : max0;
      max1 = (v1 > max1) ? v1 : max1;
      max2 = (v2 > max2) ? v2 : max2;
      max3 = (v3 > max3) ? v3 : max3;
      max4 = (v4 > max4) ? v4 : max4;
      max5 = (v5 > max5) ? v5 : max5;
      max6 = (v6 > max6) ? v6 : max6;
      max7 = (v7 > max7) ? v7 : max7;
    }
    maxval = max0;
    maxval = (max1 > maxval) ? max1 : maxval;
    maxval = (max2 > maxval) ? max2 : maxval;
    maxval = (max3 > maxval) ? max3 : maxval;
    maxval = (max4 > maxval) ? max4 : maxval;
    maxval = (max5 > maxval) ? max5 : maxval;
    maxval = (max6 > maxval) ? max6 : maxval;
    maxval = (max7 > maxval) ? max7 : maxval;
  } else if (Reduce >= 4) {
    T max0 = mX(0, inner_idx);
    T max1 = mX(1, inner_idx);
    T max2 = mX(2, inner_idx);
    T max3 = mX(3, inner_idx);
    r = 4;
    #pragma unroll 4
    for (; r + 3 < Reduce; r += 4) {
      T v0 = mX(r + 0, inner_idx);
      T v1 = mX(r + 1, inner_idx);
      T v2 = mX(r + 2, inner_idx);
      T v3 = mX(r + 3, inner_idx);
      max0 = (v0 > max0) ? v0 : max0;
      max1 = (v1 > max1) ? v1 : max1;
      max2 = (v2 > max2) ? v2 : max2;
      max3 = (v3 > max3) ? v3 : max3;
    }
    maxval = max0;
    maxval = (max1 > maxval) ? max1 : maxval;
    maxval = (max2 > maxval) ? max2 : maxval;
    maxval = (max3 > maxval) ? max3 : maxval;
  } else {
    maxval = mX(0, inner_idx);
    r = 1;
  }
  for (; r < Reduce; ++r) {
    T v = mX(r, inner_idx);
    maxval = (v > maxval) ? v : maxval;
  }

  Y[(int64_t)o * (int64_t)Inner + inner_idx] = maxval;
}

torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  int64_t ndim = x.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

  auto x_c = x.contiguous();

  // Compute Outer = product of dims before `dim`,
  // Reduce = size at `dim`,
  // Inner  = product of dims after `dim`.
  int64_t Outer = 1;
  for (int64_t i = 0; i < dim; ++i) Outer *= x_c.size(i);
  int64_t Reduce = x_c.size(dim);
  int64_t Inner = 1;
  for (int64_t i = dim + 1; i < ndim; ++i) Inner *= x_c.size(i);

  // Build output shape (input shape with `dim` removed)
  std::vector<int64_t> out_sizes;
  out_sizes.reserve(ndim - 1);
  for (int64_t i = 0; i < ndim; ++i) {
    if (i != dim) out_sizes.push_back(x_c.size(i));
  }

  auto y = torch::empty(out_sizes, x_c.options());

  constexpr int Threads = 256;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)Outer,
      (unsigned)((Inner + Threads - 1) / Threads)
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  max_reduce_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)Outer, (int)Reduce, (int)Inner
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["max_reduce_dim_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension,
    implemented with a custom CUTE/CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim_forward(x, self.dim)

